from pathlib import Path
from uuid import UUID


def save_artifact(root: Path, build_id: UUID, name: str, content: bytes) -> Path:
    target = root / str(build_id) / name
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(content)
    return target


def artifact_location(root: Path, build_id: UUID, name: str) -> str:
    return str(root / str(build_id) / name)
